UPDATE proj_result_subscription_candidate SET observed_sequence=#{query.observedSequence},
  formation_sequence=COALESCE(formation_sequence,#{query.formationSequence}),observation=#{query.observation}
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND subscription_id=#{query.subscriptionId}
  AND id=#{query.id} AND observed_sequence <= #{query.observedSequence}

UPDATE proj_result_subscription_candidate SET observed_sequence=#{query.observedSequence},observation=#{query.observation}
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND subscription_id=#{query.subscriptionId}
  AND observed_sequence <= #{query.observedSequence}


        AND result_id=#{query.resultId}
        AND object_id=#{query.objectId}

    AND object_id=#{query.objectId}
    AND 1=0
